 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==2){if(result==RESULT_OK&&data!=null&&data.getData()!=null)exportSelection(data.getData());return;}if(req!=1||result!=RESULT_OK||data==null)return;ArrayList<Uri> incoming=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)incoming.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)incoming.add(data.getData());ArrayList<Uri> selected=storedUris();HashSet<String> seen=new HashSet<>();for(Uri uri:selected)seen.add(uri.toString());for(Uri uri:incoming){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}if(seen.add(uri.toString()))selected.add(uri);}saveUris(selected);loadLibrary(selected);}
 ArrayList<Uri> storedUris(){ArrayList<Uri> out=new ArrayList<>();String raw=getPreferences(0).getString("zip_library","");for(String line:raw.split("\\n")){if(!line.isEmpty())try{out.add(Uri.parse(line));}catch(Exception ignored){}}return out;}
