 void resetLibrary(){++gen;thumbPool.getQueue().clear();pending.clear();for(ZipSession session:sessions)session.close();sessions.clear();owners.clear();all.clear();shown.clear();zip=null;archiveSignature="";synchronized(cache){cache.clear();}saveUris(new ArrayList<Uri>());selectedFolder="전체 폴더";folderPicker.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"전체 폴더"}));adapter.notifyDataSetChanged();updateTabs();status.setText("ZIP 목록 초기화 완료");}
 boolean video(ZipArchiveEntry e){return e.getName().toLowerCase(Locale.ROOT).matches(".*\\.(mp4|mkv|webm|mov|m4v|3gp)$");}
 boolean media(ZipArchiveEntry e){return video(e)||e.getName().toLowerCase(Locale.ROOT).matches(".*\\.(jpg|jpeg|png|webp|gif|bmp)$");}
