 void loadUserPrefs(){favorites.clear();hiddenZips.clear();albums.clear();cacheLimit=getPreferences(0).getLong("cache_limit",1024L*1024*1024);try{org.json.JSONObject json=new org.json.JSONObject(getPreferences(0).getString("albums","{}"));java.util.Iterator<String> names=json.keys();while(names.hasNext()){String name=names.next();Set<String> keys=new HashSet<>();org.json.JSONArray a=json.getJSONArray(name);for(int i=0;i<a.length();i++)keys.add(a.getString(i));albums.put(name,keys);}}catch(Exception ignored){}for(String k:getPreferences(0).getString("favorites","").split("\n"))if(!k.isEmpty())favorites.add(k);for(String k:getPreferences(0).getString("hidden_zips","").split("\n"))if(!k.isEmpty())hiddenZips.add(k);}
