 void exportSelection(Uri tree){ArrayList<ZipArchiveEntry> items=new ArrayList<>();for(ZipArchiveEntry e:all)if(selectedKeys.contains(thumbKey(e)))items.add(e);status.setText(items.size()+"개 파일 추출 중…");pool.execute(()->{int ok=0;for(ZipArchiveEntry e:items){try{ZipSession session=owner(e);if(session==null)continue;String name=e.getName();name=name.substring(name.lastIndexOf('/')+1);String unique=Integer.toHexString(session.uri.toString().hashCode())+"_"+name;String mime=video(e)?"video/*":"image/*";Uri output=android.provider.DocumentsContract.createDocument(getContentResolver(),android.provider.DocumentsContract.buildDocumentUriUsingTree(tree,android.provider.DocumentsContract.getTreeDocumentId(tree)),mime,unique);if(output==null)continue;try(InputStream in=session.zip.getInputStream(e);OutputStream out=getContentResolver().openOutputStream(output)){byte[] buffer=new byte[131072];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}ok++;}catch(Exception ignored){}}final int count=ok;ui.post(()->{status.setText(count+"/"+items.size()+"개 추출 완료");Toast.makeText(this,count+"개 저장됨",Toast.LENGTH_LONG).show();});});}

