 void showAlbumManager(){ArrayList<String> names=new ArrayList<>();names.add("전체 미디어");names.addAll(albums.keySet());names.add("＋ 새 앨범");new AlertDialog.Builder(this).setTitle("앨범").setItems(names.toArray(new String[0]),(d,index)->{if(index==0){activeAlbum="";filter();}else if(index==names.size()-1){final EditText input=new EditText(this);input.setHint("앨범 이름");new AlertDialog.Builder(this).setTitle("새 앨범").setView(input).setNegativeButton("취소",null).setPositiveButton("생성",(a,b)->{String name=input.getText().toString().trim();if(!name.isEmpty()){albums.putIfAbsent(name,new HashSet<>());saveUserPrefs();activeAlbum=name;filter();}}).show();}else{String name=names.get(index);new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"앨범 열기","앨범 삭제"},(a,b)->{if(b==0){activeAlbum=name;filter();}else new AlertDialog.Builder(this).setMessage("앨범만 삭제하고 원본 파일은 유지합니다.").setNegativeButton("취소",null).setPositiveButton("삭제",(c,z)->{albums.remove(name);if(activeAlbum.equals(name))activeAlbum="";saveUserPrefs();filter();}).show();}).show();}}).setNegativeButton("닫기",null).show();}
 void showLibraryManager(){ArrayList<Uri> uris=storedUris();if(uris.isEmpty()){new AlertDialog.Builder(this).setMessage("등록된 ZIP이 없습니다. ＋ 열기로 추가하세요.").setPositiveButton("확인",null).show();return;}String[] labels=new String[uris.size()];for(int i=0;i<uris.size();i++){Uri u=uris.get(i);String name=u.getLastPathSegment();labels[i]=(hiddenZips.contains(u.toString())?"○ ":"● ")+(name==null?u.toString():name);}new AlertDialog.Builder(this).setTitle("ZIP 라이브러리 · "+uris.size()+"개").setItems(labels,(d,index)->{Uri uri=uris.get(index);new AlertDialog.Builder(this).setTitle(labels[index]).setItems(new String[]{hiddenZips.contains(uri.toString())?"갤러리에 표시":"갤러리에서 숨기기","목록에서 제거","취소"},(d2,action)->{if(action==0){if(!hiddenZips.add(uri.toString()))hiddenZips.remove(uri.toString());saveUserPrefs();filter();showLibraryManager();}else if(action==1){uris.remove(index);hiddenZips.remove(uri.toString());saveUris(uris);saveUserPrefs();loadLibrary(uris);}}).show();}).setPositiveButton("닫기",null).show();}
 long directoryBytes(File dir){long total=0;File[] files=dir.listFiles();if(files!=null)for(File f:files)total+=f.isDirectory()?directoryBytes(f):f.length();return total;}
