 void showCacheLimitPicker(){String[] options={"512 MB","1 GB","3 GB","5 GB"};long[] values={512L,1024L,3072L,5120L};new AlertDialog.Builder(this).setTitle("영상 캐시 용량 제한").setSingleChoiceItems(options,-1,(d,index)->{cacheLimit=values[index]*1048576L;saveUserPrefs();pool.execute(()->trimVideoCache(cacheLimit,null));d.dismiss();showCacheManager();}).setNegativeButton("취소",null).show();}
 void showCacheManager(){File thumbs=new File(getCacheDir(),"zip_thumbs"),videos=new File(getCacheDir(),"zip_video_cache");long a=directoryBytes(thumbs),b=directoryBytes(videos);new AlertDialog.Builder(this).setTitle("캐시 관리").setMessage("썸네일: "+(a/1048576)+" MB\n영상: "+(b/1048576)+" MB\n합계: "+((a+b)/1048576)+" MB\n영상 캐시 한도: "+(cacheLimit/1048576)+" MB").setNegativeButton("닫기",null).setNeutralButton("용량 설정",(d,w)->showCacheLimitPicker()).setPositiveButton("전체 캐시 삭제",(d,w)->{clearDirectory(thumbs);clearDirectory(videos);synchronized(cache){cache.clear();}adapter.notifyDataSetChanged();}).show();}
