 void filter(){if(adapter==null)return;shown.clear();String q=search.getText().toString().toLowerCase(Locale.ROOT);long min=sizeMode==1?1048576L:sizeMode==2?10485760L:sizeMode==3?104857600L:0;for(ZipArchiveEntry e:all){ZipSession ownerSession=owner(e);if(ownerSession!=null&&hiddenZips.contains(ownerSession.uri.toString()))continue;if(favoritesOnly&&!favorites.contains(thumbKey(e)))continue;if(!activeAlbum.isEmpty()&&!albums.getOrDefault(activeAlbum,Collections.emptySet()).contains(thumbKey(e)))continue;if(activeTab==1&&video(e))continue;if(activeTab==2&&!video(e))continue;if(!"전체 폴더".equals(selectedFolder)){String n=e.getName();if(!n.startsWith(selectedFolder+"/"))continue;}if(e.getSize()<min)continue;if(e.getName().toLowerCase(Locale.ROOT).contains(q))shown.add(e);}Comparator<ZipArchiveEntry> cmp;if(sortMode==2||sortMode==3)cmp=Comparator.comparingLong(ZipArchiveEntry::getTime).thenComparing(ZipArchiveEntry::getName);else if(sortMode==4||sortMode==5)cmp=Comparator.comparingLong(ZipArchiveEntry::getSize).thenComparing(ZipArchiveEntry::getName);else cmp=Comparator.comparing(ZipArchiveEntry::getName,String.CASE_INSENSITIVE_ORDER);if(sortMode==1||sortMode==2||sortMode==4)cmp=cmp.reversed();shown.sort(cmp);adapter.notifyDataSetChanged();updateTabs();if(!all.isEmpty())status.setText(shown.size()+"개 표시 · 전체 "+all.size()+"개");}
 Bitmap decode(ZipArchiveEntry e,int size)throws Exception{ZipSession session=owner(e);ZipFile z=session==null?null:session.zip;if(z==null)return null;BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;synchronized(z){try(InputStream in=z.getInputStream(e)){BitmapFactory.decodeStream(in,null,o);}}int sample=1;while(o.outWidth/sample>size*2||o.outHeight/sample>size*2)sample*=2;BitmapFactory.Options b=new BitmapFactory.Options();b.inSampleSize=sample;synchronized(z){try(InputStream in=z.getInputStream(e)){return BitmapFactory.decodeStream(in,null,b);}}}
