 void thumbnail(ZipArchiveEntry e,ImageView iv,int id){String key=id+":"+thumbKey(e);if(!pending.add(key))return;if(thumbPool.getQueue().size()>40){pending.remove(key);return;}thumbPool.execute(()->{Bitmap b=null;File temp=null;try{if(id!=gen||Thread.currentThread().isInterrupted())return;File disk=thumbFile(e);if(disk.isFile())b=BitmapFactory.decodeFile(disk.getAbsolutePath());if(b==null&&video(e)){MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{if(e.getMethod()==ZipArchiveEntry.STORED&&e.getDataOffset()>=0){retriever.setDataSource(direct(e));}else{temp=extractVideo(e);retriever.setDataSource(temp.getAbsolutePath());}b=retriever.getFrameAtTime(1000000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);if(b!=null&&b.getWidth()>480){int h=Math.max(1,b.getHeight()*480/b.getWidth());Bitmap small=Bitmap.createScaledBitmap(b,480,h,true);if(small!=b)b.recycle();b=small;}}finally{retriever.release();}}else if(b==null)b=decode(e,240);if(b!=null&&!disk.isFile()){File dir=disk.getParentFile();if(dir.exists()||dir.mkdirs()){try(FileOutputStream out=new FileOutputStream(disk)){b.compress(Bitmap.CompressFormat.JPEG,78,out);}catch(Exception ignored){disk.delete();}}}}catch(Exception ignored){}finally{pending.remove(key);}if(b!=null&&id==gen){synchronized(cache){cache.put(thumbKey(e),b);}Bitmap result=b;ui.post(()->{if(id!=gen)return;for(int i=0;i<grid.getChildCount();i++){View child=grid.getChildAt(i);if(child instanceof FrameLayout){Object tag=child.getTag();if(tag instanceof ImageView){ImageView target=(ImageView)tag;if(thumbKey(e).equals(target.getTag()))target.setImageBitmap(result);}}}});}});}
 void trimVideoCache(long limit,File protect){File dir=new File(getCacheDir(),"zip_video_cache");File[] files=dir.listFiles();if(files==null)return;long total=0;for(File f:files)if(f.isFile())total+=f.length();if(total<=limit)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(File f:files){if(total<=limit)break;if(f.equals(protect)||f.getName().endsWith(".part"))continue;long bytes=f.length();if(f.delete())total-=bytes;}}
 File extractVideo(ZipArchiveEntry e)throws IOException{String name=e.getName(),ext=name.substring(name.lastIndexOf('.'));File dir=new File(getCacheDir(),"zip_video_cache");if(!dir.exists()&&!dir.mkdirs())throw new IOException("캐시 폴더 생성 실패");String id=Integer.toHexString(thumbKey(e).hashCode());File ready=new File(dir,id+ext);if(ready.isFile()&&ready.length()==e.getSize()){ready.setLastModified(System.currentTimeMillis());return ready;}File partial=new File(dir,id+".part");ZipSession session=owner(e);ZipFile current=session==null?null:session.zip;if(current==null)throw new IOException("ZIP 닫힘");try(InputStream in=current.getInputStream(e);OutputStream out=new FileOutputStream(partial)){byte[] buf=new byte[262144];int n;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("작업 취소");out.write(buf,0,n);}}catch(Exception ex){partial.delete();throw new IOException(ex);}if(!partial.renameTo(ready)){partial.delete();throw new IOException("영상 캐시 저장 실패");}trimVideoCache(cacheLimit,ready);return ready;}
 void photo(ZipArchiveEntry first){ArrayList<ZipArchiveEntry> photos=new ArrayList<>();for(ZipArchiveEntry e:shown)if(!video(e))photos.add(e);int start=photos.indexOf(first);if(start<0)return;Dialog dialog=new Dialog(this,android.R.style.Theme_Black_NoTitleBar_Fullscreen);FrameLayout layout=new FrameLayout(this);layout.setBackgroundColor(0xff05070b);ZoomView view=new ZoomView(this);layout.addView(view,new FrameLayout.LayoutParams(-1,-1));TextView info=text("",13);info.setPadding(dp(16),dp(16),dp(16),dp(16));info.setBackgroundColor(0x99000000);layout.addView(info,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));TextView x=text("✕",25);x.setPadding(dp(18),dp(18),dp(18),dp(18));layout.addView(x,new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT));x.setOnClickListener(v->dialog.dismiss());int[] index={start},serial={0};Runnable[] show={null};show[0]=()->{ZipArchiveEntry e=photos.get(index[0]);info.setText((index[0]+1)+" / "+photos.size()+"   "+e.getName());view.setImageDrawable(null);view.reset();int request=++serial[0];pool.execute(()->{try{Bitmap b=decode(e,2600);ui.post(()->{if(dialog.isShowing()&&request==serial[0])view.setImageBitmap(b);});}catch(Exception ignored){}});};view.swipe=d->{int n=index[0]+d;if(n>=0&&n<photos.size()){index[0]=n;show[0].run();}};dialog.setContentView(layout);dialog.show();show[0].run();}
 interface Swipe{void move(int d);}class ZoomView extends ImageView{ScaleGestureDetector scale;GestureDetector gesture;float factor=1,lastX,lastY;Swipe swipe;ZoomView(Context c){super(c);setScaleType(ScaleType.FIT_CENTER);scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){factor=Math.max(1,Math.min(5,factor*d.getScaleFactor()));setScaleX(factor);setScaleY(factor);return true;}});gesture=new GestureDetector(c,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onFling(MotionEvent a,MotionEvent b,float vx,float vy){if(factor<1.2&&Math.abs(b.getX()-a.getX())>80&&Math.abs(vx)>250&&swipe!=null){swipe.move(b.getX()<a.getX()?1:-1);return true;}return false;}public boolean onDoubleTap(MotionEvent e){factor=factor>1?1:2.5f;setScaleX(factor);setScaleY(factor);if(factor==1){setTranslationX(0);setTranslationY(0);}return true;}});}void reset(){factor=1;setScaleX(1);setScaleY(1);setTranslationX(0);setTranslationY(0);}public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);gesture.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&e.getPointerCount()==1&&factor>1.01f&&!scale.isInProgress()){float dx=e.getX()-lastX,dy=e.getY()-lastY;float boundX=getWidth()*(factor-1)/2,boundY=getHeight()*(factor-1)/2;setTranslationX(Math.max(-boundX,Math.min(boundX,getTranslationX()+dx)));setTranslationY(Math.max(-boundY,Math.min(boundY,getTranslationY()+dy)));lastX=e.getX();lastY=e.getY();}else if(e.getActionMasked()==MotionEvent.ACTION_UP&&factor<=1.01f){setTranslationX(0);setTranslationY(0);}return true;}}
